import {chromium} from 'playwright';
import assert from 'node:assert/strict';
const browser = await chromium.launch({headless:true,args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:1100}});
const errors = [];
page.on('pageerror', e=>errors.push(e.message));
await page.goto('http://localhost:5180');
await page.evaluate(()=>localStorage.clear());
await page.reload();
await page.locator('tbody tr').first().waitFor();
await page.screenshot({path:'/tmp/orbit-desktop.png',fullPage:true});
assert.equal(await page.locator('tbody tr').count(),10);
await page.getByRole('button',{name:'Сотрудник',exact:true}).click();
assert.equal(await page.locator('th[aria-sort=\"ascending\"]').count(),1);
let names = await page.locator('.employee-info strong').allTextContents();
assert.deepEqual(names,[...names].sort((a,b)=>a.localeCompare(b,'ru')));
await page.getByRole('button',{name:'Сотрудник',exact:true}).click();
assert.equal(await page.locator('th[aria-sort=\"descending\"]').count(),1);
await page.getByRole('checkbox',{name:'Выбрать всех на странице'}).check();
assert.equal(await page.locator('tbody input:checked').count(),10);
await page.getByRole('button',{name:'Следующая страница'}).click();
assert.equal(await page.locator('tbody input:checked').count(),0);
assert.match(await page.locator('.selection-bar').innerText(),/10/);
await page.getByRole('button',{name:'Предыдущая страница'}).click();
assert.equal(await page.locator('tbody input:checked').count(),10);
await page.getByRole('button',{name:'Снять выбор'}).click();
await page.getByRole('textbox',{name:'Поиск сотрудников'}).fill('Смирнова');
assert.equal(await page.locator('tbody tr').count(),1);
await page.getByRole('textbox',{name:'Поиск сотрудников'}).fill('несуществующий сотрудник');
await page.getByRole('heading',{name:'Сотрудники не найдены'}).waitFor();
await page.getByRole('button',{name:'Сбросить поиск и фильтры'}).click();
await page.getByRole('tab',{name:/В отпуске/}).click();
assert.equal(await page.locator('tbody tr').count(),6);
await page.getByRole('tab',{name:/Все сотрудники/}).click();
await page.getByRole('button',{name:'Фильтры',exact:true}).click();
await page.locator('.filters-popover select').first().selectOption('Дизайн');
await page.getByRole('button',{name:'Применить'}).click();
assert.equal(await page.locator('tbody tr').count(),8);
await page.getByRole('button',{name:'Сбросить всё'}).click();
await page.getByRole('combobox',{name:'Сотрудников на странице'}).selectOption('20');
assert.equal(await page.locator('tbody tr').count(),20);
await page.getByRole('combobox',{name:'Сотрудников на странице'}).selectOption('10');
const downloadPromise = page.waitForEvent('download');
await page.getByRole('button',{name:'Экспорт',exact:true}).click();
const download = await downloadPromise;
assert.equal(download.suggestedFilename(),'Команда_Acme.csv');
await page.getByRole('button',{name:'Добавить сотрудника',exact:true}).click();
await page.getByRole('textbox',{name:'Имя и фамилия'}).fill('Тестовый Сотрудник');
await page.getByRole('textbox',{name:'Рабочая почта'}).fill('test@acme.studio');
await page.getByRole('textbox',{name:'Должность',exact:true}).fill('Test Engineer');
await page.locator('dialog').getByRole('button',{name:'Добавить сотрудника'}).click();
assert.match(await page.locator('tbody tr').first().innerText(),/Тестовый Сотрудник/);
await page.reload();
assert.match(await page.locator('tbody tr').first().innerText(),/Тестовый Сотрудник/);
await page.getByRole('checkbox',{name:'Выбрать: Тестовый Сотрудник'}).check();
await page.locator('.selection-bar').getByRole('button',{name:'Удалить'}).click();
await page.locator('dialog').getByRole('button',{name:'Удалить',exact:true}).click();
assert.equal(await page.getByRole('checkbox',{name:'Выбрать: Тестовый Сотрудник'}).count(),0);
await page.evaluate(()=>localStorage.clear());
await page.reload();
await page.setViewportSize({width:390,height:844});
await page.screenshot({path:'/tmp/orbit-mobile.png',fullPage:true});
assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth <= innerWidth),true);
assert.deepEqual(errors,[]);
console.log('PASS: sorting, pagination, cross-page selection, search, empty state, status tabs, department filters, page sizes, CSV export, add, persistence, delete, mobile layout, no runtime errors.');
await browser.close();
EOF"

